    PhotoFileID UNIQUEIDENTIFIER NULL,
    Sequence INT NOT NULL DEFAULT 0,
    IsWriteIn BIT NOT NULL DEFAULT 0,
    Status NVARCHAR(20) NOT NULL DEFAULT N'Active',
    CONSTRAINT PK_ContestOption PRIMARY KEY (ID),
    CONSTRAINT FK_ContestOption_Contest FOREIGN KEY (ContestID) REFERENCES [${flyway:defaultSchema}].[Contest](ID),
    CONSTRAINT FK_ContestOption_CandidatePerson FOREIGN KEY (CandidatePersonID) REFERENCES [__mj_BizAppsCommon].[Person](ID),
    CONSTRAINT FK_ContestOption_StatementFile FOREIGN KEY (StatementFileID) REFERENCES [${mjSchema}].[File](ID),
    CONSTRAINT FK_ContestOption_PhotoFile FOREIGN KEY (PhotoFileID) REFERENCES [${mjSchema}].[File](ID),
    CONSTRAINT CK_ContestOption_Status CHECK (Status IN (N'Active', N'Withdrawn'))
);
GO

