    CONSTRAINT FK_Nomination_ContestOption FOREIGN KEY (ContestOptionID) REFERENCES [${flyway:defaultSchema}].[ContestOption](ID),
    CONSTRAINT UQ_Nomination_ContestNominee UNIQUE (ContestID, NomineePersonID),
    CONSTRAINT CK_Nomination_Status CHECK (Status IN (N'Submitted', N'Accepted', N'Declined', N'Approved', N'Rejected', N'Withdrawn'))
);
GO

---------------------------------------------------------------------------
-- NominationEndorsement
