    CONSTRAINT FK_BallotSelection_Contest FOREIGN KEY (ContestID) REFERENCES [${flyway:defaultSchema}].[Contest](ID),
    CONSTRAINT FK_BallotSelection_ContestOption FOREIGN KEY (ContestOptionID) REFERENCES [${flyway:defaultSchema}].[ContestOption](ID),
    CONSTRAINT CK_BallotSelection_Rank CHECK (Rank IS NULL OR Rank >= 1),
    CONSTRAINT CK_BallotSelection_OneChoice CHECK ((IsAbstain = 1 AND ContestOptionID IS NULL AND WriteInText IS NULL) OR (IsAbstain = 0 AND ContestOptionID IS NOT NULL))
);
GO

---------------------------------------------------------------------------
-- ContestRunningTally
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[ContestRunningTally] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWID(),
    ContestID UNIQUEIDENTIFIER NOT NULL,
    ContestOptionID UNIQUEIDENTIFIER NULL,
    VoteCount DECIMAL(18,6) NOT NULL DEFAULT 0,
    CONSTRAINT PK_ContestRunningTally PRIMARY KEY NONCLUSTERED (ID),
    CONSTRAINT FK_ContestRunningTally_Contest FOREIGN KEY (ContestID) REFERENCES [${flyway:defaultSchema}].[Contest](ID),
    CONSTRAINT FK_ContestRunningTally_ContestOption FOREIGN KEY (ContestOptionID) REFERENCES [${flyway:defaultSchema}].[ContestOption](ID),
    CONSTRAINT UQ_ContestRunningTally UNIQUE (ContestID, ContestOptionID)
);
GO

---------------------------------------------------------------------------
-- ResultSnapshot
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[ResultSnapshot] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ElectionID UNIQUEIDENTIFIER NOT NULL,
    SnapshotAt DATETIMEOFFSET NOT NULL DEFAULT SYSDATETIMEOFFSET(),
    BallotCount INT NOT NULL,
    Results NVARCHAR(MAX) NOT NULL,
    CONSTRAINT PK_ResultSnapshot PRIMARY KEY (ID),
    CONSTRAINT FK_ResultSnapshot_Election FOREIGN KEY (ElectionID) REFERENCES [${flyway:defaultSchema}].[Election](ID),
    CONSTRAINT CK_ResultSnapshot_BallotCount CHECK (BallotCount >= 0)
);
GO

---------------------------------------------------------------------------
-- ContestResult
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[ContestResult] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ContestID UNIQUEIDENTIFIER NOT NULL,
    Outcome NVARCHAR(20) NOT NULL,
    BallotsCounted INT NOT NULL,
    Abstentions DECIMAL(18,6) NOT NULL DEFAULT 0,
    EligibleCount INT NOT NULL,
    VotesCast DECIMAL(18,6) NOT NULL,
    Rounds NVARCHAR(MAX) NULL,
    TieBreakSeed NVARCHAR(128) NULL,
    TieBreakNotes NVARCHAR(MAX) NULL,
    ComputedAt DATETIMEOFFSET NOT NULL DEFAULT SYSDATETIMEOFFSET(),
    IsFinal BIT NOT NULL DEFAULT 0,
    CONSTRAINT PK_ContestResult PRIMARY KEY (ID),
    CONSTRAINT FK_ContestResult_Contest FOREIGN KEY (ContestID) REFERENCES [${flyway:defaultSchema}].[Contest](ID),
    CONSTRAINT CK_ContestResult_Outcome CHECK (Outcome IN (N'Passed', N'Failed', N'Decided', N'Tied', N'NoQuorum', N'Void'))
);
GO

---------------------------------------------------------------------------
-- ContestOptionResult
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[ContestOptionResult] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ContestResultID UNIQUEIDENTIFIER NOT NULL,
    ContestOptionID UNIQUEIDENTIFIER NOT NULL,
    Votes DECIMAL(18,6) NOT NULL,
    Position INT NULL,
    Outcome NVARCHAR(20) NOT NULL,
    CONSTRAINT PK_ContestOptionResult PRIMARY KEY (ID),
    CONSTRAINT FK_ContestOptionResult_ContestResult FOREIGN KEY (ContestResultID) REFERENCES [${flyway:defaultSchema}].[ContestResult](ID),
    CONSTRAINT FK_ContestOptionResult_ContestOption FOREIGN KEY (ContestOptionID) REFERENCES [${flyway:defaultSchema}].[ContestOption](ID),
    CONSTRAINT UQ_ContestOptionResult UNIQUE (ContestResultID, ContestOptionID),
    CONSTRAINT CK_ContestOptionResult_Outcome CHECK (Outcome IN (N'Elected', N'Defeated', N'Excluded', N'Tied', N'Counted'))
);
GO

---------------------------------------------------------------------------
-- ElectionCertification
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[ElectionCertification] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ElectionID UNIQUEIDENTIFIER NOT NULL,
