    ${mjSchema}_isa_p1.[Name],
    ${mjSchema}_isa_p1.[Description],
    ${mjSchema}_isa_p1.[ElectionTypeID],
    ${mjSchema}_isa_p1.[Status],
    ${mjSchema}_isa_p1.[SecrecyMode],
