    MJFile_DocumentFileID.[Name] AS [DocumentFile],
    mjBizAppsVotingElection_PriorElectionID.[Name] AS [PriorElection]
FROM
    [${flyway:defaultSchema}].[StandardsBallotElection] AS s
INNER JOIN
